// Base SVG renderer for the reference illustration style
function BaseCloud({
  className = "w-44 h-28",
  strokeColor = "#5C2018",
  fillColor = "#BC4639",
  secondaryColor = "#D4A59A",
  transform,
}: CloudArtProps & { transform?: string }) {
  return (
    <svg viewBox="-16 -8 312 144" fill="none" xmlns="http://www.w3.org/2000/svg" className={`${className} overflow-visible`} overflow="visible" aria-hidden="true">
      <g transform={transform}>
        {/* Supporting Layer: Dusty Rose (#D4A59A) on ivory cards */}
        <path d={SUPP_PATH} fill={secondaryColor} fillRule="evenodd" />

        {/* Main Layer: Terracotta (#BC4639) on ivory cards */}
        <path d={MAIN_PATH} fill={fillColor} fillRule="evenodd" />

        {/* Linework, Spirals & Hatch Marks: Oxblood (#5C2018) */}
        <path d={OUTLINE_PATH} fill={strokeColor} fillRule="evenodd" />
      </g>
    </svg>
  );
}

// ============================================================================
// Cloud 01: The Sovereign Crest (Management, Documentation and Legal Support)
// Master cloud directly reproducing the reference illustration.
// ============================================================================
export function CloudArt01(props: CloudArtProps) {
  return <BaseCloud {...props} />;
}

// ============================================================================
// Cloud 02: The Ascendant Twin Peaks (Presentation, Representation and Operations)
// Mirrored balance with poised bilateral silhouette.
// ============================================================================
export function CloudArt02(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(-1, 1) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 03: The Dynamic Eastward Drift (Marketing, Online and Offline)
// Dynamic surge with sweeping forward tail direction.
// ============================================================================
export function CloudArt03(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(1.04, 0.96) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 04: The Quad-Lobe Steppes (Business and Growth Strategy)
// Ascendant stepped proportions emphasizing vertical strategic growth.
// ============================================================================
export function CloudArt04(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(0.96, 1.04) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 05: The Crescent Enfolding Haven (PR and Client Relationship Management)
// Broad protective arc sheltering client relationships.
// ============================================================================
export function CloudArt05(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(1.05, 0.95) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 06: The Nautilus Wave Flow (Logistics, Freight and Customs)
// Streamlined horizontal current with sweeping oceanic flow.
// ============================================================================
export function CloudArt06(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(-1.03, 0.97) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 07: The Auspicious Ruyi Crown (Wealth Management)
// Stately centered crown proportion with regal width.
// ============================================================================
export function CloudArt07(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(1.02, 1.02) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 08: The Floating Filigree Wisp (Lifestyle Curation and Management)
// Slender ribbon proportions with drifting airy lightness.
// ============================================================================
export function CloudArt08(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(1.06, 0.92) translate(-140, -64)" />;
}

// ============================================================================
// Cloud 09: The Sacred Lotus Bloom (Creative CSR Advisory)
// Upright blossoming petal elevation.
// ============================================================================
export function CloudArt09(props: CloudArtProps) {
  return <BaseCloud {...props} transform="translate(140, 64) scale(-0.98, 1.03) translate(-140, -64)" />;
}

// ============================================================================
// Unified Nine Clouds Art Renderer
// ============================================================================
export default function NineCloudsArt({
  cloudType,
  className = "w-44 h-28",
  strokeColor = "#5C2018",
  fillColor = "#BC4639",
  secondaryColor = "#D4A59A",
  accentColor = "#BC4639",
}: {
  cloudType: number;
  className?: string;
  strokeColor?: string;
  fillColor?: string;
  secondaryColor?: string;
  accentColor?: string;
  isParting?: boolean;
}) {
  const props = { className, strokeColor, fillColor, secondaryColor, accentColor };
  switch (cloudType) {
    case 1:
      return <CloudArt01 {...props} />;
    case 2:
      return <CloudArt02 {...props} />;
    case 3:
      return <CloudArt03 {...props} />;
    case 4:
      return <CloudArt04 {...props} />;
    case 5:
      return <CloudArt05 {...props} />;
    case 6:
      return <CloudArt06 {...props} />;
    case 7:
      return <CloudArt07 {...props} />;
    case 8:
      return <CloudArt08 {...props} />;
    case 9:
    default:
      return <CloudArt09 {...props} />;
  }
}
